import type { Metadata } from "next";
import { Inter, DM_Sans } from "next/font/google";
import Script from "next/script";
import "./globals.css";
import Navbar from "../components/Navbar";
import Footer from "../components/Footer";

const inter = Inter({ subsets: ["latin"], variable: "--font-inter" });
const dmSans = DM_Sans({ subsets: ["latin"], variable: "--font-dm-sans" });

export const metadata: Metadata = {
  title: "Harsh Vashishtha — AI Developer & Founder",
  description: "Building intelligent AI products, autonomous agents, and modern web experiences. Founder of Haqikos.",
  keywords: ["AI Developer", "AI Agent Builder", "Web Developer", "Haqikos", "Next.js", "React", "India"],
  authors: [{ name: "Harsh Vashishtha" }],
  openGraph: {
    title: "Harsh Vashishtha — AI Developer & Founder",
    description: "Building intelligent AI products & modern web experiences. Founder of Haqikos.",
    url: "https://harshvashishtha.space",
    siteName: "Harsh Vashishtha",
    locale: "en_IN",
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
    title: "Harsh Vashishtha — AI Developer & Founder",
    description: "Building intelligent AI products & modern web experiences. Founder of Haqikos.",
    creator: "@TheHVashishtha",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <head>
        <link rel="stylesheet" href="/css/style.css" />
        <link href="https://cdn.jsdelivr.net/npm/boxicons@2.1.4/css/boxicons.min.css" rel="stylesheet" />
        <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@latest/dist/tabler-icons.min.css" />
        <meta name="google-adsense-account" content="ca-pub-6625278402778620" />
        <script 
          async 
          src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-6625278402778620"
          crossOrigin="anonymous"
        ></script>
      </head>
      <body className={`${inter.variable} ${dmSans.variable} antialiased font-sans`}>
        <Navbar />
        {children}
        <Footer />
        <Script src="/js/main.js" strategy="lazyOnload" />
      </body>
    </html>
  );
}
